selector_to_html = {"a[href=\"#aten-minor-line-pinning\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">ATen minor-line pinning<a class=\"headerlink\" href=\"#aten-minor-line-pinning\" title=\"Link to this heading\">#</a></h3><p>Torch-FL generates native bindings to PyTorch\u2019s internal ATen operator registry. Those bindings are sensitive to C++ ABI and operator schema changes, so the project pins to a PyTorch minor line \u2014 currently <strong>2.10.x</strong>. A different minor version (for example 2.11.x) produces build or runtime failures; patch releases inside the same line (2.10.0 \u2192 2.10.1) are compatible.</p>", "a[href=\"dtype-support.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Dtype support<a class=\"headerlink\" href=\"#dtype-support\" title=\"Link to this heading\">#</a></h1><p>Torch-FL preserves the requested dtype for tensor <strong>storage</strong> and follows PyTorch\u2019s promotion rules for tensor-tensor operations. Compute coverage is bounded by the vendor library each backend uses, and AMP target support is a separate question from eager dtype support: a dtype the storage layer accepts is not automatically accepted by every operator.</p>", "a[href=\"../architecture/profiler.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Profiler Integration<a class=\"headerlink\" href=\"#profiler-integration\" title=\"Link to this heading\">#</a></h1><p><code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler</span></code> supports the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device through a device tracer compiled into the wheel. A trace from <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.profiler.profile(activities=[CPU,</span> <span class=\"pre\">PrivateUse1])</span></code> is structurally equivalent to the trace of the same workload on <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.cuda</span></code>:</p>", "a[href=\"#status-definitions\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Status definitions<a class=\"headerlink\" href=\"#status-definitions\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#project-compatibility\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Project compatibility<a class=\"headerlink\" href=\"#project-compatibility\" title=\"Link to this heading\">#</a></h2><h3>ATen minor-line pinning<a class=\"headerlink\" href=\"#aten-minor-line-pinning\" title=\"Link to this heading\">#</a></h3><p>Torch-FL generates native bindings to PyTorch\u2019s internal ATen operator registry. Those bindings are sensitive to C++ ABI and operator schema changes, so the project pins to a PyTorch minor line \u2014 currently <strong>2.10.x</strong>. A different minor version (for example 2.11.x) produces build or runtime failures; patch releases inside the same line (2.10.0 \u2192 2.10.1) are compatible.</p>", "a[href=\"#reading-the-matrix\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Reading the matrix<a class=\"headerlink\" href=\"#reading-the-matrix\" title=\"Link to this heading\">#</a></h2><p>The <a class=\"reference internal\" href=\"platform-capability.html\"><span class=\"doc\">platform capability matrix</span></a> records what each accelerator builds and routes by default, and the <a class=\"reference internal\" href=\"dtype-support.html\"><span class=\"doc\">dtype support</span></a> page covers per-platform dtype and AMP boundaries. Capability ratings here describe the platform, not one build. A wheel built with a subset of kernel sets (<code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_BUILD_*</span></code>) supports a subset of what the platform can do \u2014 the wheel\u2019s own record is authoritative for that wheel.</p>", "a[href=\"#wheel-compatibility-record\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Wheel compatibility record<a class=\"headerlink\" href=\"#wheel-compatibility-record\" title=\"Link to this heading\">#</a></h3><p>Every built wheel carries <code class=\"docutils literal notranslate\"><span class=\"pre\">torch_fl/compatibility.json</span></code>, recording the selected platform and kernel sets, the bundled libtorch location, the build-time PyTorch version and C++ ABI flag, the FlagTree/FlagGems/FlagCX versions observed at build time, the declared vendor PyTorch version where one supplies device libraries, and the wheel\u2019s Python requirements. An SDK version is recorded only when the builder sets <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_SDK_VERSION</span></code> to a verified value; an absent value means <em>unknown</em>, not \u201ccompatible with all\u201d.</p>", "a[href=\"../architecture/distributed.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Distributed Collectives<a class=\"headerlink\" href=\"#distributed-collectives\" title=\"Link to this heading\">#</a></h1><p>Torch-FL provides distributed support for the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device through <code class=\"docutils literal notranslate\"><span class=\"pre\">ProcessGroupFlagOS</span></code>, a native <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.ProcessGroup</span></code> subclass. It is registered at import, so <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.init_process_group(\"flagos\")</span></code> works with no <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.distributed.*</span></code> monkeypatching.</p>", "a[href=\"platform-capability.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Platform capability matrix<a class=\"headerlink\" href=\"#platform-capability-matrix\" title=\"Link to this heading\">#</a></h1><p>What each <code class=\"docutils literal notranslate\"><span class=\"pre\">FLAGOS_ACCELERATOR</span></code> value actually provides: which operator path its wheels build, where its device runtime comes from, and which routing decisions it makes by default. This is the per-platform answer to \u201cdoes my accelerator support X at all\u201d, one level below the <a class=\"reference internal\" href=\"compatibility.html\"><span class=\"doc\">compatibility matrix</span></a> (which reports validation status per capability).</p>", "a[href=\"#compatibility-and-platform-support\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Compatibility and Platform Support<a class=\"headerlink\" href=\"#compatibility-and-platform-support\" title=\"Link to this heading\">#</a></h1><h2>Status definitions<a class=\"headerlink\" href=\"#status-definitions\" title=\"Link to this heading\">#</a></h2>", "a[href=\"../architecture/torch-compile.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">torch.compile Integration<a class=\"headerlink\" href=\"#torch-compile-integration\" title=\"Link to this heading\">#</a></h1><p>The <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device supports <code class=\"docutils literal notranslate\"><span class=\"pre\">torch.compile</span></code> for automatic kernel fusion and reduced dispatch overhead. The graph stays on the <code class=\"docutils literal notranslate\"><span class=\"pre\">flagos</span></code> device: there is no device round trip and no copy at the graph boundary.</p>", "a[href=\"#platform-matrix\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Platform matrix<a class=\"headerlink\" href=\"#platform-matrix\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
